mapper.update:
UPDATE TB_EEP_EMPLY_M
SET EMPLY_ID = #{EMPLY_ID}, EMPLY_NM = #{EMPLY_NM}, EMPLY_EMAIL = #{EMPLY_EMAIL,jdbcType=VARCHAR}, EMPLY_PH_NUM = #{EMPLY_PH_NUM,jdbcType=VARCHAR}
	, EMPLY_HOME_ADDR = #{EMPLY_HOME_ADDR,jdbcType=VARCHAR}, EMPLY_SEX_TYP_CD = #{EMPLY_SEX_TYP_CD,jdbcType=VARCHAR}
	, EMPLY_RRN = #{EMPLY_RRN}
	, EMPLY_UPDT_DT = NOW()
WHERE EMPLY_SQ = #{EMPLY_SQ}

UPDATE TB_EEP_EMPLY_M
SET EMPLY_UPDT_DT = NOW()
	, USE_YN = #{USE_YN}
	, DEL_YN = #{DEL_YN}
WHERE EMPLY_SQ = #{EMPLY_SQ}

UPDATE TB_EEP_EMPLY_M E
SET E.DEL_YN = 'Y', E.USE_YN = 'N', E.EMPLY_UPDT_DT = NOW()
WHERE E.EMPLY_AUTH_TYP_CD = '1' AND IFNULL(E.DEL_YN, 'N') = 'N'
	AND E.EMPLY_ID <> #{EMPLY_ID} AND E.EMPLY_NM = #{EMPLY_NM}
	AND #{PHONE} <> '' AND REPLACE(REPLACE(IFNULL(E.EMPLY_PH_NUM, ''), '-', ''), ' ', '') = #{PHONE}
	AND NOT EXISTS (SELECT 1 FROM TB_EEP_HR_STAFF_M S WHERE S.EMPLY_ID = E.EMPLY_ID)

mapper.select:
SELECT E.EMPLY_NM, E.EMPLY_EMAIL
	, (SELECT GROUP_CONCAT(R.ROLE_NM ORDER BY R.SORT_NO, R.ROLE_SQ SEPARATOR ', ') FROM TB_EEP_USER_ROLE_R U JOIN TB_EEP_ROLE_M R ON R.ROLE_SQ = U.ROLE_SQ WHERE U.EMPLY_ID = E.EMPLY_ID) AS ROLE_NMS
FROM TB_EEP_EMPLY_M E WHERE E.EMPLY_ID = #{emplyId}
